// True classic cached adapter: live roots, early method selection and no census pin.
let cachedSelections=0;
withSeededRandom(61991,()=>{
 const world:any=makeSimWorld('warrior',61991),actor=world.createMonster('zombie',10,'enemy');
 world.actors=[world.player,actor];const owned=new Map([['ecology-cache-witness',actor]]);
 assert.equal(massDormancyPins(world,owned).has(actor),false);
 const host=world.nativeSceneEcologyHost();assert.equal(host,world.nativeSceneEcologyHost());
 assert.equal(Object.getOwnPropertyDescriptor(world,'nativeSceneEcologyView')?.enumerable,false);
 assert.ok(!Object.keys(world).includes('nativeSceneEcologyView'));
 const changed=[actor,world.player];world.actors=changed;assert.equal(host.actors,changed);
 assert.equal(massDormancyPins(world,owned).has(actor),false);
 world.player.aiTargetId=actor.id;assert.equal(massDormancyPins(world,owned).has(actor),true);world.player.aiTargetId=-1;
 for(const [name,descriptor]of Object.entries(Object.getOwnPropertyDescriptors(host))){
  if(!descriptor.get||typeof host[name]!=='function'||typeof world[name]!=='function')continue;
  const prior=Object.getOwnPropertyDescriptor(world,name),calls:any[]=[],argument={name};
  try{
   Object.defineProperty(world,name,{configurable:true,writable:true,value:function(this:unknown,...args:unknown[]){calls.push(['old',this===world,args]);return 'old';}});
   const selected=host[name];
   Object.defineProperty(world,name,{configurable:true,writable:true,value:function(this:unknown,...args:unknown[]){calls.push(['new',this===world,args]);return 'new';}});
   assert.equal(selected(argument),'old');assert.equal(host[name](argument),'new');
   assert.equal(calls[0][2][0],argument);assert.deepEqual(calls,[['old',true,[argument]],['new',true,[argument]]]);cachedSelections++;
  }finally{if(prior)Object.defineProperty(world,name,prior);else delete world[name];}
 }
});
assert.equal(cachedSelections,16);
console.log('PASS actual World ecology cache',cachedSelections,'method selections and true controller pin control');
